classes.content:
self button[role="tab"] {
	/* font-size: 0.8vw !important; */
	color: #65676b;
	padding: 12px;
	border-radius: 6px;
}

self button[role="tab"][aria-selected="true"] {
	color:#216fdb;
}

self button[role="tab"]:hover {
	background-color: #dedede !important;
}

self button[role="tab"] {
	font-size: 0.8vw !important;
	color: #b0b3b8;
	padding: 12px;
	border-radius: 6px;
}

self button[role="tab"][aria-selected="true"] {
	color:#4599ff;
}

self button[role="tab"]:hover {
	background-color: #3a3a3a !important;
}

self {
	display: -webkit-box;
    -webkit-box-orient: vertical;
    overflow: hidden;
    -webkit-line-clamp: 1;
	text-overflow: ellipsis;
    max-width: 100%;
}

self .innerScrollContainer > div:hover {
	background-color: transparent;
}
self .innerScrollContainer > div.selected{
	background-color: transparent;

}

self {
	display: -webkit-box;
    -webkit-box-orient: vertical;
    overflow: hidden;
    -webkit-line-clamp: 1;
	text-overflow: ellipsis;
    max-width: 100%;
}

self:has(p span[title="true"]) {
	color:#e4e6eb !important;
	background-color: #1c1e21 !important;
	border: 1px solid #e4e6eb;
}

self{
	transition: transform .2s;
}

self:hover {
  	transform: scale(1.2);
}

self:has(p span[title="Public"])::before {
	content: "\f0b1";
	font-family: FontAwesome;
	font-weight: 500 !important;
	margin-right: 4px;
}

self:has(p span[title="Private"])::before {
	content: "\f023";
	font-family: FontAwesome;
	font-weight: 500 !important;
	margin-right: 4px;
}

self:has(p span[title="Chat"])::before {
	content: "\f27a";
	font-family: FontAwesome;
	font-weight: 500 !important;
	margin-right: 4px;
}

/*to eliminate the purple background when selecting an item*/
self .virtualizer-list .virtualizer-item.selected {
	background-color: transparent;
}

self:has(p span:empty)::before {
	content: "\f068";
	 font-family: FontAwesome;
    font-style: normal;
    font-weight: normal;
}
